const CACHE = "raven-v4";
/* brand-fonts:start - generated by scripts/gen_theme_css.py --print-fonts precache, do not edit */
const PRECACHE_FONTS = [
  "/fonts/IBMPlexMono-400-cyrillic.woff2",
  "/fonts/IBMPlexMono-400-latin.woff2",
  "/fonts/IBMPlexMono-500-cyrillic.woff2",
  "/fonts/IBMPlexMono-500-latin.woff2",
  "/fonts/IBMPlexMono-600-cyrillic.woff2",
  "/fonts/IBMPlexMono-600-latin.woff2",
  "/fonts/IBMPlexSans-cyrillic.woff2",
  "/fonts/IBMPlexSans-latin.woff2",
  "/fonts/SpaceGrotesk-latin.woff2",
];
/* brand-fonts:end */
const STATIC_ASSETS = [
  "/",
  "/index.html",
  "/manifest.json",
  "/offline.html",
  "/favicon.svg",
  "/favicon.ico",
  "/icons/icon-192.svg",
  "/icons/icon-512.svg",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  ...PRECACHE_FONTS,
];
const API_CACHE = "raven-api-v1";

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => {
      return cache.addAll(STATIC_ASSETS);
    })
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE && k !== API_CACHE).map((k) => caches.delete(k)))
    )
  );
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (request.method !== "GET") return;

  // API requests: network first, fallback to cache
  if (url.pathname.startsWith("/api/")) {
    event.respondWith(networkFirstWithApiCache(request));
    return;
  }

  // WebSocket: don't cache
  if (url.pathname.startsWith("/ws")) return;

  // Static assets: cache first
  event.respondWith(cacheFirstWithOffline(request));
});

async function cacheFirstWithOffline(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    // Only a page can be replaced by the offline document. Handing it to a font or a script instead
    // returns HTML where a binary face was expected, and the reader sees a console error and a page in
    // the system font rather than a message about the gateway.
    if (request.mode === "navigate") {
      const offline = await caches.match("/offline.html");
      if (offline) return offline;
    }
    return new Response("Raven is offline. Reconnect, then reload this page.\n", {
      status: 503,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  }
}

async function networkFirstWithApiCache(request) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(API_CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    const cached = await caches.match(request);
    if (cached) return cached;
    return new Response(JSON.stringify({ error: "offline" }), {
      status: 503,
      headers: { "Content-Type": "application/json" },
    });
  }
}

// ── Push Notifications ──────────────────────────────────────────

self.addEventListener("push", (event) => {
  let data = { title: "Raven AI", body: "New notification", url: "/" };
  if (event.data) {
    try {
      data = Object.assign(data, event.data.json());
    } catch {
      data.body = event.data.text();
    }
  }
  event.waitUntil(
    self.registration.showNotification(data.title, {
      body: data.body,
      icon: "/icons/icon-192.png",
      badge: "/icons/icon-192.png",
      vibrate: [200, 100, 200],
      tag: "raven-notification",
      renotify: true,
      requireInteraction: true,
      data: { url: data.url || "/" },
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification.data?.url || "/";
  event.waitUntil(
    self.clients
      .matchAll({ type: "window", includeUncontrolled: true })
      .then((clientList) => {
        for (const client of clientList) {
          if (client.url.startsWith(self.location.origin) && "focus" in client) {
            client.focus();
            client.navigate(url);
            return;
          }
        }
        if ("openWindow" in self.clients) {
          self.clients.openWindow(url);
        }
      })
  );
});
